{"file_path":"src/sheet.js","content":"export class SheetError extends Error {}

export function parseAddress(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  let col = 0
  for (const ch of letters) col = col * 26 + (ch.charCodeAt(0) - 64)
  return { col, row, addr: letters + row }
}

export function colName(col) {
  return col <= 26
    ? String.fromCharCode(64 + col)
    : String.fromCharCode(64 + Math.floor((col - 1) / 26)) + String.fromCharCode(65 + ((col - 1) % 26))
}

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const cells = new Map()
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^[^ \t]*/.exec(line)
    const word = m[0]
    let rest = line.slice(word.length)
    rest = rest.replace(/^[ \t]+/, '')
    const a = parseAddress(word)
    if (!a) throw new SheetError(`error: line ${i + 1}: invalid cell address ${word.toUpperCase()}`)
    if (cells.has(a.addr)) throw new SheetError(`error: line ${i + 1}: cell ${a.addr} is declared twice`)
    cells.set(a.addr, { addr: a.addr, col: a.col, row: a.row, content: rest })
  })
  return cells
}
"}

